  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2018-spring-am-24','exam-sg','暗号技術・メッセージ認証符号','standard','single_choice','【平成30年度 春期 午前 問24】メッセージが改ざんされていないかどうかを確認するために，そのメッセージから，ブロック暗号を用いて生成することができるものはどれか。','[{"id":"a","text":"PKI"},{"id":"b","text":"パリティビット"},{"id":"c","text":"メッセージ認証符号"},{"id":"d","text":"ルート証明書"}]','"c"','メッセージ認証符号（MAC）は，メッセージの完全性確認などに用いられる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-25','exam-sg','認証・リスクベース認証','standard','single_choice','【平成30年度 春期 午前 問25】リスクベース認証に該当するものはどれか。','[{"id":"a","text":"インターネットからのアクセスには，常にワンタイムパスワードを要求する。"},{"id":"b","text":"インターネットバンキングの取引時に，乱数表を用いた認証を要求する。"},{"id":"c","text":"アクセス元のIPアドレスなどを分析し，通常と異なるネットワークからのアクセスには追加認証を要求する。"},{"id":"d","text":"記憶，所持，生体情報のうち二つ以上を組み合わせて認証する。"}]','"c"','リスクベース認証はアクセス環境などからリスクを評価し，リスクが高い場合に追加認証を求める。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-26','exam-sg','暗号技術・暗号アルゴリズムの危殆化','standard','single_choice','【平成30年度 春期 午前 問26】暗号アルゴリズムの危殆化を説明したものはどれか。','[{"id":"a","text":"強度の高い暗号アルゴリズムを使用した製品の輸入が制限されること"},{"id":"b","text":"鍵の管理が不適切なために，暗号鍵が漏えいする危険性が高まること"},{"id":"c","text":"コンピュータの計算能力の向上などによって鍵の推測が可能になり，安全性が低下すること"},{"id":"d","text":"高性能なコンピュータと膨大な時間・費用を使って暗号化を行い，暗号の強度を高めること"}]','"c"','計算能力の向上などによって従来の暗号を現実的に解読できるようになり，安全性が低下することを危殆化という。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-27','exam-sg','暗号解読・ブルートフォース攻撃','standard','single_choice','【平成30年度 春期 午前 問27】暗号解読の手法のうち，ブルートフォース攻撃はどれか。','[{"id":"a","text":"平文と暗号文の組を手掛かりに，鍵の候補を総当たりで試す。"},{"id":"b","text":"暗号文の統計的な偏りを利用して鍵を推定する線形解読法を用いる。"},{"id":"c","text":"暗号処理中の電磁波などを測定し，秘密情報を推定する。"},{"id":"d","text":"入力差分と出力差分の関係を利用して鍵を推定する差分解読法を用いる。"}]','"a"','ブルートフォース攻撃は，鍵の候補を総当たりで試す方法である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja'),
('sg-official-2018-spring-am-28','exam-sg','メールセキュリティ・S/MIME','standard','single_choice','【平成30年度 春期 午前 問28】電子メールの本文を暗号化するために使用される方式はどれか。','[{"id":"a","text":"BASE64"},{"id":"b","text":"GZIP"},{"id":"c","text":"PNG"},{"id":"d","text":"S/MIME"}]','"d"','S/MIMEは電子メールの暗号化や電子署名に用いられる規格である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000f01f-att/2018h30h_sg_am_qs.pdf','ja');
